mapper.select:
SELECT id, user_id AS userId, attempt_id AS attemptId, type, amount,
       balance_after AS balanceAfter, reason, operator_id AS operatorId, created_at AS createdAt
FROM credit_transactions

    user_id = #{userId}
    AND type = #{type}
    AND created_at >= #{startTime}
    AND created_at <= #{endTime}

ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM credit_transactions

    user_id = #{userId}
    AND type = #{type}
    AND created_at >= #{startTime}
    AND created_at <= #{endTime}
